#include "scheduler.h"

#include <assert.h>
#include <stdio.h>

static void test_paused_scheduler_rejects_submit_and_run_next(void) {
    Scheduler s;
    scheduler_init(&s);
    scheduler_submit(&s, 1, "a");
    scheduler_pause(&s);

    assert(scheduler_submit(&s, 1, "b") == -1);

    int id;
    assert(scheduler_run_next(&s, &id) == 0);
}

static void test_paused_scheduler_rejects_retry(void) {
    Scheduler s;
    scheduler_init(&s);
    int id = scheduler_submit(&s, 1, "a");
    int running_id;
    scheduler_run_next(&s, &running_id);
    scheduler_fail(&s, id);

    scheduler_pause(&s);
    assert(scheduler_retry(&s, id) == -1);

    scheduler_resume(&s);
    assert(scheduler_retry(&s, id) != -1);
}

int main(void) {
    test_paused_scheduler_rejects_submit_and_run_next();
    test_paused_scheduler_rejects_retry();
    printf("PASS\n");
    return 0;
}

