#pragma once

#include "job.h"
#include "queue.h"

#define SCHEDULER_MAX_RUNNING 256
#define SCHEDULER_MAX_HISTORY 256

typedef struct {
    JobQueue pending;
    Job running[SCHEDULER_MAX_RUNNING];
    int running_count;
    Job history[SCHEDULER_MAX_HISTORY];
    int history_count;
    int paused;
} Scheduler;

void scheduler_init(Scheduler *s);
void scheduler_pause(Scheduler *s);
void scheduler_resume(Scheduler *s);

/* Rejects (-1) while paused. */
int scheduler_submit(Scheduler *s, int priority, const char *payload);

/* Rejects (0) while paused, even if jobs are pending. */
int scheduler_run_next(Scheduler *s, int *out_id);

int scheduler_complete(Scheduler *s, int id);
int scheduler_fail(Scheduler *s, int id);

/* Moves a FAILED job from history back into the pending queue for
 * another attempt (a fresh id is assigned). Rejects (-1) if the job
 * isn't FAILED, or if the scheduler is paused - retries are a form of
 * new work and must also be held back while paused. */
int scheduler_retry(Scheduler *s, int id);

int scheduler_find_state(const Scheduler *s, int id, JobState *out_state);

